<body>
  <h1>二次函数：a、b、c 与抛物线</h1>
  <div class="sub">拖动三个系数，实时观察开口方向、开口宽窄、对称轴、顶点与 y 轴截距如何变化。</div>

  <div class="wrap">
    <div class="card">
      <canvas id="cv" width="900" height="560" aria-label="二次函数抛物线图像"></canvas>
      <div class="legend">
        <span><i style="background:#ffb74d"></i>顶点</span>
        <span><i style="background:#66bb6a"></i>实根（与 x 轴交点）</span>
        <span><i style="background:#4fc3f7"></i>y 轴截距 c</span>
        <span><i style="background:#8e9bff"></i>对称轴</span>
      </div>
    </div>

    <div class="panel">
      <div class="ctrl">
        <label for="a">系数 a <span class="val" id="aOut">1.00</span></label>
        <input id="a" type="range" min="-3" max="3" step="0.05" value="1">
      </div>
      <div class="ctrl">
        <label for="b">系数 b <span class="val" id="bOut">0.00</span></label>
        <input id="b" type="range" min="-8" max="8" step="0.1" value="0">
      </div>
      <div class="ctrl">
        <label for="c">系数 c <span class="val" id="cOut">-2.00</span></label>
        <input id="c" type="range" min="-10" max="10" step="0.1" value="-2">
      </div>

      <div class="readout">
        <div class="mini"><div class="k">开口方向</div><div class="v" id="openDir">向上</div></div>
        <div class="mini"><div class="k">对称轴 x</div><div class="v" id="axisX">0.00</div></div>
        <div class="mini"><div class="k">顶点</div><div class="v" id="vertex">(0.00, -2.00)</div></div>
        <div class="mini"><div class="k">判别式 Δ</div><div class="v" id="disc">8.00</div></div>
        <div class="mini wide"><div class="k">与 x 轴交点</div><div class="v" id="roots">x₁ = -1.41, x₂ = 1.41</div></div>
      </div>

      <div class="btns" style="margin-top:12px;">
        <button id="btnReset" type="button">↺ 重置为标准型</button>
        <button id="btnFit" type="button">⤢ 自动缩放视图</button>
      </div>
      <div class="hint">提示：当 a→0 时曲线退化为直线，不再是抛物线；此时对称轴与顶点公式失效，读数会标注“退化”。</div>

      <div class="assume">
        <b>数学假设：</b>函数为 \(y=ax^2+bx+c\)，定义域为全体实数。对称轴 \(x=-b/(2a)\)，顶点 \((-b/2a,\; c-b^2/4a)\)，判别式 \(\Delta=b^2-4ac\)。
        Δ&gt;0 有两实根，Δ=0 有一重根，Δ&lt;0 无实根（曲线不与 x 轴相交）。c 即 x=0 时的函数值，是 y 轴截距。
        视图为固定比例尺的直角坐标系，可点“自动缩放”按当前曲线重新适配。
      </div>
    </div>
  </div>

<script>
(function(){
  const cv = document.getElementById("cv");
  const ctx = cv.getContext("2d");
  const aEl = document.getElementById("a");
  const bEl = document.getElementById("b");
  const cEl = document.getElementById("c");
  const aOut = document.getElementById("aOut");
  const bOut = document.getElementById("bOut");
  const cOut = document.getElementById("cOut");
  const openDirEl = document.getElementById("openDir");
  const axisXEl = document.getElementById("axisX");
  const vertexEl = document.getElementById("vertex");
  const discEl = document.getElementById("disc");
  const rootsEl = document.getElementById("roots");
  const btnReset = document.getElementById("btnReset");
  const btnFit = document.getElementById("btnFit");

  // 视图范围（世界坐标）
  let view = { xmin:-10, xmax:10, ymin:-12, ymax:12 };

  function restore(){
    let s = {};
    try { s = genui.getState() || {}; } catch(e){ s = {}; }
    aEl.value = (typeof s.a === "number") ? s.a : 1;
    bEl.value = (typeof s.b === "number") ? s.b : 0;
    cEl.value = (typeof s.c === "number") ? s.c : -2;
    if(s.view && typeof s.view.xmin === "number"){
      view = { xmin:s.view.xmin, xmax:s.view.xmax, ymin:s.view.ymin, ymax:s.view.ymax };
    }
  }
  function save(){
    try {
      genui.setState({
        a: Number(aEl.value),
        b: Number(bEl.value),
        c: Number(cEl.value),
        view: { xmin:view.xmin, xmax:view.xmax, ymin:view.ymin, ymax:view.ymax }
      });
    } catch(e){}
  }

  function niceStep(span, targetTicks){
    const raw = span / targetTicks;
    const mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const norm = raw / mag;
    let step;
    if(norm < 1.5) step = 1;
    else if(norm < 3) step = 2;
    else if(norm < 7) step = 5;
    else step = 10;
    return step * mag;
  }

  function worldToScreen(x, y, W, H, pad){
    const plotW = W - pad.l - pad.r;
    const plotH = H - pad.t - pad.b;
    const sx = pad.l + (x - view.xmin) / (view.xmax - view.xmin) * plotW;
    const sy = pad.t + (view.ymax - y) / (view.ymax - view.ymin) * plotH;
    return [sx, sy];
  }

  function draw(){
    const a = Number(aEl.value);
    const b = Number(bEl.value);
    const c = Number(cEl.value);

    // 读数
    aOut.textContent = a.toFixed(2);
    bOut.textContent = b.toFixed(2);
    cOut.textContent = c.toFixed(2);

    const degenerate = Math.abs(a) < 1e-9;
    const disc = b*b - 4*a*c;
    const axisX = degenerate ? NaN : -b/(2*a);
    const vy = degenerate ? NaN : (a*axisX*axisX + b*axisX + c);

    openDirEl.textContent = degenerate ? "退化为直线" : (a > 0 ? "向上" : "向下");
    axisXEl.textContent = degenerate ? "—" : axisX.toFixed(2);
    vertexEl.textContent = degenerate ? "—" : "(" + axisX.toFixed(2) + ", " + vy.toFixed(2) + ")";
    discEl.textContent = disc.toFixed(2);

    if(degenerate){
      rootsEl.textContent = "无（一次方程 b·x+c=0）";
    } else if(disc > 1e-9){
      const r1 = (-b - Math.sqrt(disc)) / (2*a);
      const r2 = (-b + Math.sqrt(disc)) / (2*a);
      const lo = Math.min(r1, r2), hi = Math.max(r1, r2);
      rootsEl.textContent = "x₁ = " + lo.toFixed(2) + ", x₂ = " + hi.toFixed(2);
    } else if(Math.abs(disc) <= 1e-9){
      rootsEl.textContent = "重根 x = " + (-b/(2*a)).toFixed(2);
    } else {
      rootsEl.textContent = "无实根（Δ < 0）";
    }

    // 画布绘制
    const W = cv.width, H = cv.height;
    const pad = { l:56, r:20, t:20, b:40 };
    const plotW = W - pad.l - pad.r;
    const plotH = H - pad.t - pad.b;

    ctx.clearRect(0,0,W,H);
    ctx.fillStyle = "#0b131b";
    ctx.fillRect(0,0,W,H);

    // 网格
    const xStep = niceStep(view.xmax - view.xmin, 10);
    const yStep = niceStep(view.ymax - view.ymin, 8);
    ctx.font = "11px system-ui, sans-serif";
    ctx.lineWidth = 1;

    // 竖线
    const xStart = Math.ceil(view.xmin / xStep) * xStep;
    for(let x = xStart; x <= view.xmax + 1e-9; x += xStep){
      const [sx] = worldToScreen(x, 0, W, H, pad);
      ctx.strokeStyle = Math.abs(x) < 1e-9 ? "#36506a" : "#1b2a38";
      ctx.beginPath(); ctx.moveTo(sx, pad.t); ctx.lineTo(sx, pad.t + plotH); ctx.stroke();
      ctx.fillStyle = "#8aa0b4";
      ctx.textAlign = "center";
      if(Math.abs(x) > 1e-9){
        ctx.fillText(formatTick(x), sx, pad.t + plotH + 16);
      }
    }
    // 横线
    const yStart = Math.ceil(view.ymin / yStep) * yStep;
    for(let y = yStart; y <= view.ymax + 1e-9; y += yStep){
      const [, sy] = worldToScreen(0, y, W, H, pad);
      ctx.strokeStyle = Math.abs(y) < 1e-9 ? "#36506a" : "#1b2a38";
      ctx.beginPath(); ctx.moveTo(pad.l, sy); ctx.lineTo(pad.l + plotW, sy); ctx.stroke();
      ctx.fillStyle = "#8aa0b4";
      ctx.textAlign = "right";
      if(Math.abs(y) > 1e-9){
        ctx.fillText(formatTick(y), pad.l - 7, sy + 4);
      }
    }

    // 坐标轴
    ctx.strokeStyle = "#4a6480";
    ctx.lineWidth = 1.5;
    if(view.ymin < 0 && view.ymax > 0){
      const [, sy0] = worldToScreen(0, 0, W, H, pad);
      ctx.beginPath(); ctx.moveTo(pad.l, sy0); ctx.lineTo(pad.l + plotW, sy0); ctx.stroke();
    }
    if(view.xmin < 0 && view.xmax > 0){
      const [sx0] = worldToScreen(0, 0, W, H, pad);
      ctx.beginPath(); ctx.moveTo(sx0, pad.t); ctx.lineTo(sx0, pad.t + plotH); ctx.stroke();
    }

    // 对称轴
    if(!degenerate && axisX > view.xmin && axisX < view.xmax){
      ctx.setLineDash([6,5]);
      ctx.strokeStyle = "#8e9bff";
      ctx.lineWidth = 1.5;
      const [sxA] = worldToScreen(axisX, 0, W, H, pad);
      ctx.beginPath(); ctx.moveTo(sxA, pad.t); ctx.lineTo(sxA, pad.t + plotH); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "#8e9bff";
      ctx.textAlign = "left";
      ctx.fillText("x = " + axisX.toFixed(2), sxA + 5, pad.t + 13);
    }

    // 抛物线
    ctx.strokeStyle = "#4fc3f7";
    ctx.lineWidth = 2.4;
    ctx.lineJoin = "round";
    ctx.beginPath();
    let started = false;
    const N = 900;
    for(let i=0;i<=N;i++){
      const x = view.xmin + (view.xmax - view.xmin) * i / N;
      const y = a*x*x + b*x + c;
      const [sx, sy] = worldToScreen(x, y, W, H, pad);
      if(sy < pad.t - 2000 || sy > pad.t + plotH + 2000){ started = false; continue; }
      if(!started){ ctx.moveTo(sx, sy); started = true; }
      else ctx.lineTo(sx, sy);
    }
    ctx.stroke();

    // y 轴截距 c
    if(c >= view.ymin && c <= view.ymax){
      const [sxc, syc] = worldToScreen(0, c, W, H, pad);
      ctx.fillStyle = "#4fc3f7";
      ctx.beginPath(); ctx.arc(sxc, syc, 5, 0, Math.PI*2); ctx.fill();
    }

    // 实根
    if(!degenerate && disc >= -1e-9){
      const sq = Math.sqrt(Math.max(disc,0));
      const rs = disc > 1e-9 ? [(-b-sq)/(2*a), (-b+sq)/(2*a)] : [ -b/(2*a) ];
      for(const r of rs){
        if(r >= view.xmin && r <= view.xmax){
          const [sxr, syr] = worldToScreen(r, 0, W, H, pad);
          ctx.fillStyle = "#66bb6a";
          ctx.beginPath(); ctx.arc(sxr, syr, 5, 0, Math.PI*2); ctx.fill();
        }
      }
    }

    // 顶点
    if(!degenerate && axisX >= view.xmin && axisX <= view.xmax && vy >= view.ymin && vy <= view.ymax){
      const [sxv, syv] = worldToScreen(axisX, vy, W, H, pad);
      ctx.fillStyle = "#ffb74d";
      ctx.beginPath(); ctx.arc(sxv, syv, 6, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = "#0b131b"; ctx.lineWidth = 1.5; ctx.stroke();
      ctx.fillStyle = "#ffb74d";
      ctx.textAlign = "left";
      ctx.fillText("顶点", sxv + 9, syv - 8);
    }

    // 轴名
    ctx.fillStyle = "#8aa0b4";
    ctx.textAlign = "center";
    ctx.fillText("x", pad.l + plotW/2, H - 6);
    ctx.save();
    ctx.translate(16, pad.t + plotH/2);
    ctx.rotate(-Math.PI/2);
    ctx.fillText("y", 0, 0);
    ctx.restore();

    // 公式
    ctx.fillStyle = "#e8eef5";
    ctx.font = "13px system-ui, sans-serif";
    ctx.textAlign = "left";
    ctx.fillText(equationText(a,b,c), pad.l + 6, pad.t - 4);
  }

  function formatTick(v){
    const r = Math.round(v*1000)/1000;
    return Number.isInteger(r) ? String(r) : r.toFixed(1);
  }

  function equationText(a,b,c){
    const f = n => (Math.abs(n) < 1e-9 ? "0" : (Math.round(n*100)/100).toString());
    const sign = n => n < 0 ? " − " : " + ";
    return "y = " + f(a) + "x²" + sign(b) + f(Math.abs(b)) + "x" + sign(c) + f(Math.abs(c));
  }

  function autoFit(){
    const a = Number(aEl.value), b = Number(bEl.value), c = Number(cEl.value);
    let xmin = -10, xmax = 10;
    let ys = [];
    for(let i=0;i<=200;i++){
      const x = xmin + (xmax - xmin) * i / 200;
      ys.push(a*x*x + b*x + c);
    }
    let ymin = Math.min.apply(null, ys);
    let ymax = Math.max.apply(null, ys);
    if(Math.abs(a) > 1e-9){
      const vx = -b/(2*a);
      const vy = a*vx*vx + b*vx + c;
      ymin = Math.min(ymin, vy);
      ymax = Math.max(ymax, vy);
    }
    if(ymin === ymax){ ymin -= 1; ymax += 1; }
    const padY = (ymax - ymin) * 0.12;
    view = { xmin:xmin, xmax:xmax, ymin:ymin - padY, ymax:ymax + padY };
    draw();
    save();
  }

  function onChange(){
    draw();
    save();
  }

  aEl.addEventListener("input", onChange);
  bEl.addEventListener("input", onChange);
  cEl.addEventListener("input", onChange);

  btnReset.addEventListener("click", function(){
    aEl.value = 1; bEl.value = 0; cEl.value = -2;
    view = { xmin:-10, xmax:10, ymin:-12, ymax:12 };
    draw(); save();
  });

  btnFit.addEventListener("click", autoFit);

  restore();
  draw();
  save();
})();
</script>
</body>
</html>

怎么读这个实验

a 的符号：a > 0 开口向上、顶点是最低点；a < 0 开口向下、顶点是最高点。a 的绝对值越大，开口越窄（曲线更“陡”），越小越宽；a 接近 0 时曲线趋近一条直线，此时不再是抛物线。

对称轴 x = −b/(2a)：改变 b 会让对称轴左右移动，也带着顶点一起移动；注意 b 的影响方向还受 a 的符号左右。

